import { Sparkles } from "lucide-react";

/**
 * Renders the human-readable "why this match" text generated by
 * server/src/modules/matching/match.engine.js (buildExplanation()).
 */
export default function MatchExplanation({ explanation }) {
  if (!explanation) return null;

  return (
    <div className="flex items-start gap-2 rounded-xl bg-brand-50 px-3.5 py-3 text-sm text-brand-800">
      <Sparkles size={16} className="mt-0.5 shrink-0 text-brand-500" />
      <p>{explanation}</p>
    </div>
  );
}
